function makeSections(L) {
  const authored = CONTENT[L.n] ?? cardSections(CARDS[L.n], L.n);
  return authored.map((section, index) => {
    const image = section.image ? null : imageFor(L.n, index + 1);
    return { ...section, ...(image ? { image: image[0], imageAlt: image[1] } : {}) };
  });
}

function esc(value) {
  return value.replace(/\\/g, "\\\\").replace(/`/g, "\\`").replace(/\$\{/g, "\\${");
}

function sectionTs(section) {
  let output = `      { id: ${JSON.stringify(section.id)}, kicker: ${JSON.stringify(section.kicker)}, title: ${JSON.stringify(section.title)}, body: \`${esc(section.body)}\``;
  if (section.image) output += `, image: ${JSON.stringify(section.image)}, imageAlt: ${JSON.stringify(section.imageAlt)}`;
  if (section.callout) output += `, callout: { label: ${JSON.stringify(section.callout.label)}, text: ${JSON.stringify(section.callout.text)} }`;
  if (section.checkIn) output += `, checkIn: check(${JSON.stringify(section.checkIn.prompt)}, ${JSON.stringify(section.checkIn.choices)}, ${section.checkIn.correctIndex}, ${JSON.stringify(section.checkIn.explanation)})`;
  return `${output} }`;
}

function lessonFile(L) {
  const sections = makeSections(L);
  const quiz = sections.filter((section) => section.checkIn).slice(0, 7).map((section, index) => {
    const c = section.checkIn;
    return `    { id: "q${index + 1}", question: ${JSON.stringify(c.prompt)}, choices: ${JSON.stringify(c.choices)}, correctIndex: ${c.correctIndex}, explanation: ${JSON.stringify(c.explanation)} }`;
  });
  const prev = L.n === 1 ? "" : `  prevHref: "/learn/advanced-ai/${L.n - 1}",\n`;
  const next = L.n === 16 ? "" : `  nextHref: "/learn/advanced-ai/${L.n + 1}",\n`;
  return `import type { AILessonConfig } from "@/components/ai/AILessonCanvas";

const check = (prompt: string, choices: string[], correctIndex: number, explanation: string) => ({
  prompt, choices, correctIndex, explanation,
});

export const advancedAiLesson${L.n}: AILessonConfig = {
  id: "aai-${L.n}",
  title: ${JSON.stringify(`${L.n}. ${L.title}`)},
  goal: ${JSON.stringify(L.goal)},
  xpReward: ${50 + (L.n - 1) * 50},
  badge: ${JSON.stringify(L.badge)},
  dashboardHref: "/dashboard",
${prev}${next}  lessonModule: {
    durationLabel: "~40–50 min lesson",
    sections: [
${sections.map(sectionTs).join(",\n")}
    ],
  },
  bigIdeas: ${JSON.stringify([
    `Apply ${L.title} with measurable evidence rather than impressive anecdotes.`,
    "Preserve meaningful failures and use them to improve the next release.",
    "Define a safe recovery path before users depend on the system.",
  ])},
  keyTerms: ${JSON.stringify([
    { term: "Evidence", definition: "Observable results that support or challenge a system claim." },
    { term: "Failure mode", definition: "A predictable way a system can produce an incorrect or harmful result." },
    { term: "Guardrail", definition: "A technical or human control that limits unsafe behavior." },
    { term: L.title, definition: `The topic investigated in this lesson: ${L.goal}` },
  ])},
  realWorld: ${JSON.stringify(`Teams applying ${L.title} earn trust by preserving evidence, monitoring failures, and documenting limits—not by claiming perfection.`)},
  quiz: [
${quiz.join(",\n")}
  ],
  reflection: { prompt: ${JSON.stringify(`Apply ${L.title} to a real problem. State one test or metric, one likely failure, and one safeguard.`)}, placeholder: "Write your answer…" },
};
`;
}

function pageFile(n) {
  return `"use client";

import { AILessonCanvas } from "@/components/ai/AILessonCanvas";
import { advancedAiLesson${n} } from "@/lib/advancedAiLessons/lesson${n}";

export default function Page() {
  return <AILessonCanvas lesson={advancedAiLesson${n}} hubLabel="Advanced AI Hub" />;
}
`;
}

fs.mkdirSync(lessonsDir, { recursive: true });
for (const lesson of LESSONS) {
  fs.writeFileSync(path.join(lessonsDir, `lesson${lesson.n}.ts`), lessonFile(lesson));
  const pagePath = path.join(pagesDir, String(lesson.n), "page.tsx");
  fs.mkdirSync(path.dirname(pagePath), { recursive: true });
  fs.writeFileSync(pagePath, pageFile(lesson.n));
}
console.log(`Generated ${LESSONS.length} Advanced AI lessons and pages; interactive exercises were left untouched.`);
